import os,glob,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    # Parse all demo pairs and test input
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[]
        start=m.end()
        lines=t[start:].split('\n')[:h]
        for line in lines:
            if '==' in line or '|' in line:
                rows.append(line.split('==')[0].strip('|'))
        rows=[r.strip() for r in rows if r.strip()]
        if k not in G and len(rows)==h and w==w:
            G[k]=[[int(x) for x in r.split()] for r in rows]
    return G
G=load()
print("All keys:", sorted(G.keys()))

