        if files:
            print("Files:", files[:10])
    except:
        pass

def f_debug(grid):
    h = len(grid)

    separators = []
    bg_val_candidates = {}
    for r in range(h):
        vals = set(grid[r])
        if len(vals) == 1:
            val = list(vals)[0]
            bg_val_candidates[val] = bg_val_candidates.get(val, 0) + 1
            separators.append(r)

    print("Separators:", separators)
    print("bg_val_candidates:", bg_val_candidates)
    bg_val = max(bg_val_candidates.items(), key=lambda x: x[1])[0]
    print("bg_val:", bg_val)

    result = [row[:] for row in grid]

    for r in range(h):
        if r not in separators and len(set(result[r])) == 1 and result[r][0] == bg_val:
            if separators:
                min_dist = min(abs(r - s) for s in separators)
                print(f"Row {r}: min_dist={min_dist}, will_change={min_dist==1}")
                if min_dist == 1:
                    new_row = [bg_val] * len(result[r])
                    for c in range(1, len(new_row)-1):
                        new_row[c] = 3
                    result[r] = new_row

    return result

